import{_ as e,o as a,c as t,a0 as i}from"./chunks/framework.BdKrsJIB.js";const u=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md"}'),o={name:"getting-started.md"};function r(n,s,l,h,p,d){return a(),t("div",null,[...s[0]||(s[0]=[i('<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>tarsi is the org&#39;s release plane: it turns conventional commits into a release — changelog → semver bump → tag → publish. There is <strong>no <code>tarsi</code> CLI</strong>; the surface is <code>tarsi-serve</code>, an ndjson ops binary with a one-shot front door (PL-014, org ledger ADR-0003).</p><h2 id="install-tarsi-serve" tabindex="-1">Install <code>tarsi-serve</code> <a class="header-anchor" href="#install-tarsi-serve" aria-label="Permalink to &quot;Install `tarsi-serve`&quot;">​</a></h2><p>The command ships as a tamias pack (<code>libraries/tarsi</code> — <code>type: files</code> declaring <code>tarsi-serve</code> as a <code>tools/bin/&lt;triple&gt;/</code> payload bin).</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># From a tarsi checkout:</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xtask</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pack</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # release-build → libraries/tarsi/tools/bin/&lt;triple&gt;/</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./libraries/tarsi</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # deploys `tarsi-serve` onto PATH</span></span></code></pre></div><p>Dev shortcut without tamias:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xtask</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # release `tarsi-serve` → ~/.local/bin</span></span></code></pre></div><h2 id="check-the-wire" tabindex="-1">Check the wire <a class="header-anchor" href="#check-the-wire" aria-label="Permalink to &quot;Check the wire&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tarsi-serve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manifest</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># → {&quot;name&quot;:&quot;tarsi-serve&quot;,&quot;version&quot;:&quot;…&quot;,&quot;ops&quot;:[&quot;manifest&quot;,&quot;profiles&quot;,&quot;plan&quot;,&quot;changelog&quot;,&quot;notes&quot;,&quot;release&quot;]}</span></span></code></pre></div><p>Two modes:</p><ul><li><strong>No args</strong> — ndjson JSON-lines loop on stdio: one <code>{&quot;op&quot;: …, &quot;params&quot;: …}</code> per line in, one <code>{&quot;ok&quot;: …, &quot;result&quot;|&quot;error&quot;}</code> per line out.</li><li><strong><code>tarsi-serve &lt;op&gt; [--dir D] [--set k=v]… [--yes|--dry-run]</code></strong> — one-shot via <code>hypha-serve-cli</code>; prints the result JSON, exit 0/1. <code>--yes</code> maps to <code>dry_run: false</code>; <code>--dry-run</code> forces the default.</li></ul><h2 id="plan-your-first-release" tabindex="-1">Plan your first release <a class="header-anchor" href="#plan-your-first-release" aria-label="Permalink to &quot;Plan your first release&quot;">​</a></h2><p>Inside a repo with a <code>tarsi.toml</code> (or none — units default to cargo workspace members):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tarsi-serve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plan</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p>The result lists each unit in topo order: inferred bump, new version, tag, rendered changelog markdown, and publish targets — all computed, nothing written. The full walkthrough is in <a href="/tarsi/tutorials/first-release.html">Your first release</a>.</p>',15)])])}const k=e(o,[["render",r]]);export{u as __pageData,k as default};
